-- Books of the home library
CREATE TABLE books (
    -- Generated by the database, never sent by the client
                       id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
                       title          VARCHAR(255) NOT NULL,
                       author         VARCHAR(255) NOT NULL,
    -- Optional: some books have no ISBN. Text, because of hyphens and the final X
                       isbn           VARCHAR(20),
                       genre          VARCHAR(100),
    -- Stored as text; the values match the ReadingStatus enum
                       reading_status VARCHAR(20)  NOT NULL,
    -- Optional; values match the Origin enum
                       origin         VARCHAR(20),
    -- Optional; the contract only allows 1 to 5
                       rating         INTEGER,
                       CONSTRAINT chk_books_rating CHECK (rating BETWEEN 1 AND 5)
);

-- Unique ISBN only when present: several books may have no ISBN
CREATE UNIQUE INDEX uq_books_isbn ON books (isbn) WHERE isbn IS NOT NULL;